
#include "xparameters.h"
#include "xgpio.h"
#include "xuartps.h"
#include "xstatus.h"
#include "xil_types.h"
#include "xuartps.h"

/* AXI GPIO instance generated by Vivado */
#define GPIO_DEVICE_ID XPAR_AXI_GPIO_0_DEVICE_ID

/* Select the UART instance connected to the onboard USB-UART bridge. */
#if defined(XPAR_XUARTPS_1_DEVICE_ID)
    #define UART_DEVICE_ID XPAR_XUARTPS_0_DEVICE_ID
#elif defined(XPAR_PS7_UART_1_DEVICE_ID)
    #define UART_DEVICE_ID XPAR_PS7_UART_1_DEVICE_ID
#elif defined(XPAR_XUARTPS_0_DEVICE_ID)
    #define UART_DEVICE_ID XPAR_XUARTPS_0_DEVICE_ID
#else
    #error "UART device ID not found. Check xparameters.h"
#endif

#define GPIO_INPUT_CHANNEL   1
#define GPIO_OUTPUT_CHANNEL  2

#define REQUEST_MASK  0x00010000U
#define RESULT_MASK   0x00010000U
#define UART_BAUDRATE  115200U

static XGpio Gpio;
static XUartPs Uart;

/* Initialize the PS UART. */
static int init_uart(void)
{
    XUartPs_Config *cfg;

    cfg = XUartPs_LookupConfig(UART_DEVICE_ID);
    if (cfg == NULL)
        return XST_FAILURE;

    if (XUartPs_CfgInitialize(
            &Uart, cfg, cfg->BaseAddress) != XST_SUCCESS)
        return XST_FAILURE;

    XUartPs_SetOperMode(&Uart, XUARTPS_OPER_MODE_NORMAL);

    if (XUartPs_SetBaudRate(
            &Uart, UART_BAUDRATE) != XST_SUCCESS)
        return XST_FAILURE;

    return XST_SUCCESS;
}

/* Receive exactly len bytes from UART. */
static void uart_read_exact(u8 *buf, u32 len)
{
    u32 count = 0;

    while (count < len) {
        count += XUartPs_Recv(
            &Uart, buf + count, len - count);
    }
}

/* Transmit exactly len bytes over UART. */
static void uart_write_exact(const u8 *buf, u32 len)
{
    u32 count = 0;

    while (count < len) {
        count += XUartPs_Send(
            &Uart, (u8 *)(buf + count), len - count);
    }

    while (XUartPs_IsSending(&Uart)) {
        /* Wait until transmission completes. */
    }
}

int main(void)
{
    u8 rx[2];
    u8 tx[2];

    u16 sample;
    u16 result;
    //u32 gpio_value;
    u32 timeout;

    /* Initialize AXI GPIO. */
    if (XGpio_Initialize(&Gpio, GPIO_DEVICE_ID)
            != XST_SUCCESS)
        return XST_FAILURE;

    /* Channel 1: 17-bit output to FPGA filter. */
    XGpio_SetDataDirection(
        &Gpio, GPIO_INPUT_CHANNEL, 0x00000000U);

    /* Channel 2: 17-bit input from FPGA filter. */
    XGpio_SetDataDirection(
        &Gpio, GPIO_OUTPUT_CHANNEL, 0xFFFFFFFFU);

    /* Start with request low. */
    XGpio_DiscreteWrite(&Gpio, GPIO_INPUT_CHANNEL, 0);

    /* Initialize UART. */
    if (init_uart() != XST_SUCCESS)
        return XST_FAILURE;

    /*
     * MATLAB protocol:
     * Receive 2 bytes (little-endian sample).
     * Process one sample in FPGA.
     * Transmit 2 bytes (little-endian result).
     */
    while (1) {

        /* 1. Receive a 16-bit sample from MATLAB. */
        uart_read_exact(rx, 2);

        sample = (u16)rx[0]
               | ((u16)rx[1] << 8);

        /* 2. Put sample on GPIO with request low. */
        XGpio_DiscreteWrite(
            &Gpio, GPIO_INPUT_CHANNEL, (u32)sample);

        /* 3. Raise request: bit 16 = 1. */
        XGpio_DiscreteWrite(
            &Gpio, GPIO_INPUT_CHANNEL,
            (u32)sample | REQUEST_MASK);

        /* 4. Wait for the FPGA result-valid acknowledgement. */
        timeout = 100000000U;

        while ((XGpio_DiscreteRead(
                    &Gpio, GPIO_OUTPUT_CHANNEL)
                    & RESULT_MASK) == 0U) {

            if (--timeout == 0U) {
                /* Lower request before accepting another sample. */
                XGpio_DiscreteWrite(
                    &Gpio, GPIO_INPUT_CHANNEL, (u32)sample);

                /* Send 0xFFFF as an error result. */
                tx[0] = 0xFF;
                tx[1] = 0xFF;
                uart_write_exact(tx, 2);
                goto next_sample;
            }
        }

        /* 5. Read the stable 16-bit filtered result. */
        result = (u16)(XGpio_DiscreteRead(
                    &Gpio, GPIO_OUTPUT_CHANNEL) & 0xFFFFU);

        /* 6. Lower request to acknowledge the result. */
        XGpio_DiscreteWrite(
            &Gpio, GPIO_INPUT_CHANNEL, (u32)sample);

        /* 7. Wait until FPGA clears result-valid. */
        timeout = 100000000U;

        while ((XGpio_DiscreteRead(
                    &Gpio, GPIO_OUTPUT_CHANNEL)
                    & RESULT_MASK) != 0U) {

            if (--timeout == 0U)
                break;
        }

        /* 8. Return result to MATLAB, low byte first. */
        tx[0] = (u8)(result & 0xFFU);
        tx[1] = (u8)(result >> 8);

        uart_write_exact(tx, 2);

        next_sample:
        ;
    }

    return 0;
}